import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { apply, bucketOfEvent, ledgerPath, lineOf, noticeOf, recordOf, splitOf, thresholdOf } from "../index.js";

/** One settled step: usage is present, projections are the token-meter views. */
const session = { header: { id: "s-1" } };
const event = {
  type: "assistant/message",
  seq: 42,
  time: 1795000000000,
  data: {
    turn: 2,
    step: 3,
    message: { source: { provider: "deepseek-official", model: "deepseek-v4-flash" } },
    usage: {
      inputTokens: 900,
      outputTokens: 120,
      cacheReadTokens: 4000,
      cacheWriteTokens: 50,
      reasoningTokens: 30
    }
  }
};
const values = {
  contextBreakdown: { systemTokens: 1000, toolsTokens: 5000, messageTokens: 6000 },
  contextPressure: { pressureTokens: 12500, contextWindow: 128000 }
};

test("recordOf maps the breakdown, pressure, and usage", () => {
  const record = recordOf(session, event, values);
  assert.deepEqual(record, {
    v: 1,
    t: 1795000000000,
    s: "s-1",
    turn: 2,
    step: 3,
    seq: 42,
    p: "deepseek-official",
    m: "deepseek-v4-flash",
    ctx: 12500,
    win: 128000,
    sys: 1000,
    tools: 5000,
    msg: 6000,
    inp: 900,
    out: 120,
    cr: 4000,
    cw: 50,
    rs: 30
  });
});

test("recordOf falls back to the composed surface when pressure is absent", () => {
  const record = recordOf(session, event, {
    contextBreakdown: { systemTokens: 10, toolsTokens: 20, messageTokens: 30 }
  });
  assert.equal(record.ctx, 60);
  assert.equal(record.win, 0);
});

test("recordOf tolerates a missing snapshot and missing usage", () => {
  const bare = {
    type: "assistant/message",
    seq: 1,
    time: 2,
    data: { turn: 1, step: 1, message: { source: {} } }
  };
  const record = recordOf(session, bare, {});
  assert.equal(record.ctx, 0);
  assert.equal(record.sys, 0);
  assert.equal(record.inp, 0);
  assert.equal(record.p, "");
});

test("recordOf returns null when the session has no id", () => {
  assert.equal(recordOf({ header: {} }, event, values), null);
  assert.equal(recordOf(undefined, event, values), null);
});

test("lineOf emits one newline-terminated JSON object", () => {
  const line = lineOf(recordOf(session, event, values));
  assert.ok(line.endsWith("\n"));
  assert.equal(line.split("\n").length, 2);
  assert.equal(JSON.parse(line).s, "s-1");
});

test("apply writes one line per assistant settlement and skips subagents", async () => {
  const home = await mkdtemp(join(tmpdir(), "ledger-"));
  const previous = process.env.DSH_HOME;
  process.env.DSH_HOME = home;
  try {
    assert.equal(ledgerPath(), join(home, "context-ledger.jsonl"));
    const listeners = {};
    const ctx = {
      logger: { warn() {} },
      sessionProjections: { snapshot: () => ({ values }) },
      on(name, listener) {
        listeners[name] = listener;
      }
    };
    apply(ctx);
    assert.equal(typeof listeners["session/event"], "function");

    // A subagent settlement is ignored.
    listeners["session/event"]({ header: { id: "sub", origin: "subagent" } }, event);
    // A durable update that is not a settlement is ignored.
    listeners["session/event"](session, { type: "tool/result", seq: 1, data: {} });
    listeners["session/event"](session, event);

    // The write is queued; give the microtask/IO queue a turn.
    await new Promise((resolve) => setTimeout(resolve, 50));
    const text = await readFile(join(home, "context-ledger.jsonl"), "utf8");
    const lines = text.trim().split("\n");
    assert.equal(lines.length, 1);
    const record = JSON.parse(lines[0]);
    assert.equal(record.s, "s-1");
    assert.equal(record.cr, 4000);
  } finally {
    if (previous === undefined) {
      delete process.env.DSH_HOME;
    } else {
      process.env.DSH_HOME = previous;
    }
    await rm(home, { recursive: true, force: true });
  }
});

test("thresholdOf mirrors the compaction budget", () => {
  // 1M window, 64k reserved output, 64k headroom: the ratio budget wins.
  assert.equal(thresholdOf(1048576, 65536), 838860);
  // A small window makes the headroom the binding constraint.
  assert.equal(thresholdOf(65536, 0), 0);
  // No window, no threshold.
  assert.equal(thresholdOf(0, 0), 0);
  assert.equal(thresholdOf(undefined, 0), 0);
});

test("bucketOfEvent names the four message buckets", () => {
  assert.equal(bucketOfEvent({ type: "tool/result" }), "tr");
  assert.equal(bucketOfEvent({ type: "assistant/message" }), "au");
  assert.equal(bucketOfEvent({ type: "user/message", data: { source: { kind: "user" } } }), "u");
  assert.equal(bucketOfEvent({ type: "user/message", data: { source: { kind: "time-context" } } }), "ij");
  assert.equal(bucketOfEvent({ type: "system/message" }), null);
  assert.equal(bucketOfEvent(undefined), null);
});

test("noticeOf keeps injections, model switches, and compactions", () => {
  const injected = noticeOf({
    type: "user/message",
    data: { source: { kind: "time-context" }, content: [{ type: "text", text: "x".repeat(400) }] }
  });
  assert.equal(injected.kind, "inject");
  assert.equal(injected.label, "time-context");
  assert.ok(injected.delta >= 100);

  assert.equal(noticeOf({ type: "user/message", data: { source: { kind: "user" } } }), null);
  assert.equal(noticeOf({ type: "tool/result", data: {} }), null);

  assert.deepEqual(noticeOf({ type: "model/selection", data: { provider: "p", model: "deepseek-v4-pro" } }), {
    kind: "model",
    label: "deepseek-v4-pro",
    delta: 0
  });

  const compacted = noticeOf({ type: "compaction/summary", data: { model: "deepseek-v4-flash", shadowedTokenCount: 24000 } });
  assert.equal(compacted.kind, "compact");
  assert.equal(compacted.delta, -24000);

  const pruned = noticeOf({ type: "compaction/prune", data: { shadowedTokenCount: 900 } });
  assert.equal(pruned.kind, "prune");
  assert.equal(pruned.delta, -900);
});

test("recordOf carries the split and the compaction budget", () => {
  const record = recordOf(session, event, values, {
    split: { u: 100, au: 200, tr: 300, ij: 400 },
    threshold: 838860,
    reserved: 65536
  });
  assert.equal(record.u, 100);
  assert.equal(record.au, 200);
  assert.equal(record.tr, 300);
  assert.equal(record.ij, 400);
  assert.equal(record.thr, 838860);
  assert.equal(record.rsv, 65536);

  // Without the extra facts the additive keys stay absent, not zero.
  const plain = recordOf(session, event, values);
  assert.equal("u" in plain, false);
  assert.equal("thr" in plain, false);
});

test("splitOf scales the four buckets onto the authoritative total", () => {
  const nodes = [
    { seq: 1, tokens: 600 },
    { seq: 2, tokens: 100 },
    { seq: 3, tokens: 100 },
    { seq: 4, tokens: 200 },
    { seq: 5, tokens: 5000 }
  ];
  const bySeq = new Map([
    [1, { type: "tool/result" }],
    [2, { type: "assistant/message" }],
    [3, { type: "user/message", data: { source: { kind: "user" } } }],
    [4, { type: "user/message", data: { source: { kind: "ontology" } } }],
    [5, { type: "system/message" }]
  ]);
  const ctx = { get: () => ({ measure: () => ({ nodes }) }) };
  const fake = { eventAt: (seq) => bySeq.get(seq) };
  const split = splitOf(ctx, fake, 1000);
  assert.deepEqual(split, { u: 100, au: 100, tr: 600, ij: 200 });
  // No meter, no split.
  assert.equal(splitOf({ get: () => undefined }, fake, 1000), null);
  // No message budget, no split.
  assert.equal(splitOf(ctx, fake, 0), null);
});

test("apply writes settlement, event, and step lines in commit order", async () => {
  const home = await mkdtemp(join(tmpdir(), "ledger-v2-"));
  const previous = process.env.DSH_HOME;
  process.env.DSH_HOME = home;
  try {
    const listeners = {};
    const ctx = {
      logger: { warn() {} },
      sessionProjections: {
        snapshot: () => ({
          values: {
            contextBreakdown: { systemTokens: 1000, toolsTokens: 5000, messageTokens: 6000 },
            contextPressure: { pressureTokens: 12500, contextWindow: 1048576 }
          }
        })
      },
      get: (name) => name === "tokenMeter"
        ? { measure: () => ({ nodes: [{ seq: 5, tokens: 6000 }] }) }
        : undefined,
      on(name, listener) {
        listeners[name] = listener;
      }
    };
    const fire = (session, next) => listeners["session/event"](session, next);
    apply(ctx);

    const live = {
      header: { id: "s-1" },
      eventAt: (seq) => (seq === 5 ? { type: "assistant/message" } : undefined),
      requestHeader: () => ({ config: { maxTokens: 65536 } })
    };

    fire(live, { type: "turn/start", time: 900, data: { turn: 1 } });
    fire(live, { type: "step/start", time: 1000, data: { turn: 1, step: 1 } });
    fire(live, {
      type: "model/selection",
      time: 1100,
      seq: 2,
      data: { provider: "deepseek-official", model: "deepseek-v4-pro" }
    });
    fire(live, {
      type: "user/message",
      time: 1200,
      seq: 3,
      data: { source: { kind: "time-context" }, content: [{ type: "text", text: "noon" }] }
    });
    fire(live, {
      type: "tool/call",
      time: 2000,
      seq: 4,
      data: { turn: 1, step: 1, callId: "c-1", name: "read", arguments: "{}" }
    });
    fire(live, {
      type: "tool/result",
      time: 2300,
      seq: 5,
      data: { turn: 1, step: 1, message: { source: { kind: "tool", callId: "c-1" }, toolCallId: "c-1", content: [] } }
    });
    fire(live, { ...event, seq: 6, data: { ...event.data, turn: 1, step: 1 } });
    fire(live, { type: "step/end", time: 4000, data: { turn: 1, step: 1 } });

    await new Promise((resolve) => setTimeout(resolve, 80));
    const lines = (await readFile(join(home, "context-ledger.jsonl"), "utf8")).trim().split("\n").map(JSON.parse);
    assert.deepEqual(lines.map((line) => line.k ?? "settle"), ["e", "e", "settle", "s"]);

    const [, injected, settlement, step] = lines;
    assert.equal(injected.kind, "inject");
    assert.equal(injected.label, "time-context");
    assert.equal(injected.turn, 1);
    assert.equal(injected.step, 1);
    assert.equal(lines[0].kind, "model");
    assert.equal(settlement.thr, 838860);
    assert.equal(settlement.rsv, 65536);
    assert.deepEqual(
      { u: settlement.u, au: settlement.au, tr: settlement.tr, ij: settlement.ij },
      { u: 0, au: 6000, tr: 0, ij: 0 }
    );
    assert.equal(step.ms, 3000);
    assert.equal(step.tool, 300);
    assert.equal(step.n, 1);
  } finally {
    if (previous === undefined) {
      delete process.env.DSH_HOME;
    } else {
      process.env.DSH_HOME = previous;
    }
    await rm(home, { recursive: true, force: true });
  }
});
